/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/

void rsr_parking_pattern (Rsr_Prk_Pattern pattern)
{
    switch (pattern)
    { 
        case RSR_PRK_CONSTANT :  rsr_vars.prk_pattern = pattern ; rsr_parking_on  () ; break ;
        case RSR_PRK_STOP     : rsr_vars.prk_pattern = pattern ; rsr_parking_off () ; break ;
        default               : break ;
    }	
}
//--------------------------------------------------------------------------//
void rsr_parking_on (void)
{
	#if RSR_PARKING_ENA == 1
      RSR_PARKING_SET ;	
    #endif
	cmd_q_insert (INPUT_PARKING | INPUT_ON, RSR_CMD_INSERT_TIMEOUT) ;
}
//--------------------------------------------------------------------------//
void rsr_parking_off (void)
{
	#if RSR_PARKING_ENA == 1
      RSR_PARKING_CLR ;
    #endif
	cmd_q_insert (INPUT_PARKING, RSR_CMD_INSERT_TIMEOUT) ;
}

